text:
.body.plans .plan .actionSlot :is(button, a) {
  display: flex;
  align-items: center;
  justify-content: center;
  white-space: normal;
  width: 100%;
  height: auto;
  min-height: 58px;
  padding: 14px;
  border: 1px solid var(--upgrade-border);
  border-radius: 13px;
  background: var(--upgrade-surface);
  color: var(--upgrade-text);
  font-size: 17px;
  line-height: 1.4;
  font-weight: 600;
  text-decoration: none;
}
.body.plans .plan .primary :is(button, a) {
  background: var(--upgrade-grad);
  color: var(--upgrade-btn-fg);
  font-size: 15px;
  font-weight: 700;
  border-color: transparent;
  box-shadow: none;
}
.body.plans .plan .actionSlot :is(button, a):disabled {
  opacity: 1;
  background: var(--upgrade-surface2);
  color: var(--upgrade-muted);
}
.body.plans .plan .actionSlot :is(button, a):focus-visible {
  outline: 2px solid var(--pricing-accent);
  outline-offset: 3px;
}

.body tbody:last-child tr:last-child > * {
  border-bottom: 0;
}

:global([data-appearance="vercel"]) .body {
  font-family: Arial, Helvetica, system-ui, sans-serif;
}

.fineCard {
  transition:
    translate 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 220ms ease,
    border-color 220ms ease,
    background-color 250ms,
    color 250ms;
}
@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .fineCard:hover {
    translate: 0 -4px;
    border-color: var(--pricing-accent);
    box-shadow: 0 14px 32px var(--pricing-shadow);
  }
}
